package build

import (
	"fmt"
	"strings"
	"testing"
)

// A repository with thousands of top-level directories cannot name each of them within the
// bound: the index still stays bounded and its counts stay true.
func TestFileIndexVeryWideRepositoryStaysBounded(t *testing.T) {
	t.Parallel()
	var sb strings.Builder
	total := 0
	for d := 0; d < 3000; d++ {
		for f := 0; f < 20; f++ {
			fmt.Fprintf(&sb, "dir-%05d-with-a-long-name/file-%02d.txt\x00", d, f)
			total++
		}
	}
	out := fileIndex(sb.String(), []string{"dir-00001-with-a-long-name/file-01.txt"})
	if len(out) > fileIndexBytes {
		t.Fatalf("index is %d bytes, want at most %d", len(out), fileIndexBytes)
	}
	if !strings.Contains(out, fmt.Sprintf("total paths: %d\n", total)) || !strings.Contains(out, "dir-00001-with-a-long-name/file-01.txt\n") {
		t.Fatalf("index lost the true total or a required path:\n%.600s", out)
	}
}

// Exercise both root-only omissions and a parent directory that also has omitted
// descendants. Summary entries must partition the paths not listed individually.
func TestFileIndexOmissionsAndInputOrder(t *testing.T) {
	t.Parallel()
	var paths []string
	for _, dir := range []string{"", "alpha/", "alpha/deep/", "beta/deeper/"} {
		for i := 0; i < 1200; i++ {
			paths = append(paths, fmt.Sprintf("%sfile-%04d-%s.txt", dir, i, strings.Repeat("x", 70)))
		}
	}
	required := []string{paths[1199], paths[len(paths)-1]}
	out := fileIndex(strings.Join(paths, "\x00")+"\x00", required)
	// BEGIN bound
	if len(out) > fileIndexBytes {
		t.Fatalf("index is %d bytes, want at most %d", len(out), fileIndexBytes)
	}
	// END bound
	_, listedAndSummary, ok := strings.Cut(out, "## Listed paths\n")
	if !ok {
		t.Fatal("fixture did not exercise a summarized index")
	}
	listedText, summary, ok := strings.Cut(listedAndSummary, "\n## Omitted directories\n")
	if !ok {
		t.Fatal("fixture did not produce an omission summary")
	}
	listed := map[string]bool{}
	for _, p := range strings.Split(strings.TrimSuffix(listedText, "\n"), "\n") {
		listed[p] = true
	}
	// BEGIN required
	for _, p := range required {
		if !listed[p] {
			t.Errorf("required path is not listed individually: %q", p)
		}
	}
	// END required
	// BEGIN accounting
	var omitted []string
	omittedByDir := map[string]int{}
	for _, p := range paths {
		if !listed[p] {
			omitted = append(omitted, p)
			d := "."
			if i := strings.LastIndexByte(p, '/'); i >= 0 {
				d = p[:i]
			}
			omittedByDir[d]++
		}
	}
	for _, dir := range []string{".", "alpha", "alpha/deep", "beta/deeper"} {
		if omittedByDir[dir] == 0 {
			t.Fatalf("fixture has no omitted paths in %q", dir)
		}
	}
	coverage := make(map[string]int)
	total := 0
	entries := 0
	for _, line := range strings.Split(strings.TrimSpace(summary), "\n") {
		dir, countText, ok := strings.Cut(line, ": ")
		var count int
		if !ok {
			t.Fatalf("invalid omission line %q", line)
		}
		if n, err := fmt.Sscanf(countText, "%d omitted paths", &count); n != 1 || err != nil {
			t.Fatalf("invalid omission count %q", line)
		}
		want := 0
		for _, p := range omitted {
			matches := strings.HasPrefix(p, dir)
			if dir == "./" {
				matches = !strings.Contains(p, "/")
			}
			if matches {
				want++
				coverage[p]++
			}
		}
		if count != want || count == 0 {
			t.Errorf("summary %q counts %d paths, want %d from omitted set", dir, count, want)
		}
		total += count
		entries++
	}
	if entries < 2 {
		t.Fatal("fixture must exercise disjoint root and nested summary entries")
	}
	if total != len(omitted) {
		t.Errorf("summary counts %d omitted paths, omitted set has %d", total, len(omitted))
	}
	for _, p := range omitted {
		if coverage[p] != 1 {
			t.Fatalf("omitted path %q covered %d times, want exactly once", p, coverage[p])
		}
	}
	if !strings.Contains(out, fmt.Sprintf("omitted paths: %d\n", len(omitted))) {
		t.Errorf("omitted total disagrees with the omitted path set")
	}
	// END accounting
	// BEGIN order
	for i, j := 0, len(paths)-1; i < j; i, j = i+1, j-1 {
		paths[i], paths[j] = paths[j], paths[i]
	}
	reordered := fileIndex(strings.Join(paths, "\x00")+"\x00", required)
	if out != reordered {
		t.Fatal("file index changed after reversing the same input path listing")
	}
	// END order
}

